<?php
require 'includes/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$preco=(float)str_replace(',','.',$_POST['preco']??0);$d=[trim($_POST['codigo']??''),trim($_POST['nome']??''),trim($_POST['descricao']??''),trim($_POST['unidade']??'serv'),$preco];if(!$d[1]){flash('error','Informe o nome do serviço.');redirect('servicos.php');}if($id){$pdo->prepare("UPDATE orcamentos_servicos SET codigo=?,nome=?,descricao=?,unidade=?,preco=? WHERE id=?")->execute([...$d,$id]);}else{$pdo->prepare("INSERT INTO orcamentos_servicos(codigo,nome,descricao,unidade,preco) VALUES(?,?,?,?,?)")->execute($d);}flash('success','Serviço salvo.');redirect('servicos.php');}
if(isset($_GET['desativar'])){$pdo->prepare("UPDATE orcamentos_servicos SET ativo=0 WHERE id=?")->execute([(int)$_GET['desativar']]);flash('success','Serviço desativado.');redirect('servicos.php');}
$edit=null;if(isset($_GET['editar'])){$st=$pdo->prepare("SELECT * FROM orcamentos_servicos WHERE id=?");$st->execute([(int)$_GET['editar']]);$edit=$st->fetch();}$lista=$pdo->query("SELECT * FROM orcamentos_servicos WHERE ativo=1 ORDER BY nome")->fetchAll();require 'includes/header.php';?>
<div class="page-head"><h1>Serviços</h1></div><form class="card" method="post"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><div><label>Código</label><input name="codigo" value="<?= e($edit['codigo']??'') ?>"></div><div><label>Nome *</label><input required name="nome" value="<?= e($edit['nome']??'') ?>"></div><div class="full"><label>Descrição</label><textarea name="descricao"><?= e($edit['descricao']??'') ?></textarea></div><div><label>Unidade</label><input name="unidade" value="<?= e($edit['unidade']??'serv') ?>"></div><div><label>Preço padrão</label><input type="number" min="0" step="0.01" name="preco" value="<?= e((string)($edit['preco']??'0.00')) ?>"></div></div><p><button class="btn">Salvar serviço</button></p></form>
<h2>Serviços ativos</h2><table><thead><tr><th>Código</th><th>Serviço</th><th>Un.</th><th>Preço</th><th></th></tr></thead><tbody><?php foreach($lista as $r):?><tr><td><?= e($r['codigo']) ?></td><td><strong><?= e($r['nome']) ?></strong><br><span class="muted"><?= e($r['descricao']) ?></span></td><td><?= e($r['unidade']) ?></td><td><?= money((float)$r['preco']) ?></td><td class="actions"><a class="btn secondary" href="?editar=<?= (int)$r['id'] ?>">Editar</a><a data-confirm="Desativar este serviço?" class="btn danger" href="?desativar=<?= (int)$r['id'] ?>">Desativar</a></td></tr><?php endforeach;?></tbody></table><?php require 'includes/footer.php';?>
